 * In summary, the following functions can be called from other modules:
 *
 * -# background_init() at the beginning background_at_tau(),
 * -# background_at_z(), background_tau_of_z(), background_z_of_tau() at any later time
 * -# background_free() at the end, when no more calls to the previous functions are needed
 *
 * For units and normalisation conventions, there are two guiding principles:
 *
 * 1) All quantities are expressed in natural units in which everything is in powers of Mpc, e.g.:
 *
 * - t stands for (cosmological or proper time)*c in Mpc
 * - tau stands for (conformal time)*c in Mpc
 * - H stands for (Hubble parameter)/c in \f$ Mpc^{-1} \f$
 * - etc.
 *
 * 2) New since v3.0: all quantities that should normally scale with some power of
 * a_0^n are renormalised by a_0^{-n}, in order to be independent of a_0, e.g.
 *
 * - a in the code stands for \f$ a/a_0 \f$ in reality
 * - tau in the code stands for \f$ a_0 \tau c \f$ in Mpc
 * - any prime in the code stands for \f$ (1/a_0) d/d\tau \f$
 * - r stands for any comoving radius times a_0
 * - etc.
 */

#include "background.h"
#include <gsl/gsl_integration.h>

static double background_gedf_ca2_from_params(
                                              double s_a_gedf,
                                              double wi_gedf,
                                              double wf_gedf,
                                              double a,
                                              double w_gedf,
                                              double dw_over_da_gedf
                                              ) {

  double one_plus_w = 1. + w_gedf;
  double B = s_a_gedf * (1. + wf_gedf);

  if (fabs(one_plus_w) > 1.e-10) {
    return w_gedf - a * dw_over_da_gedf / 3. / one_plus_w;
  }
  if (fabs(1. + wi_gedf) < 1.e-10) {
    return wi_gedf - B / 3.;
  }
  return w_gedf;
}

static double background_gedf_ca2(
                                  struct background * pba,
                                  double a,
                                  double w_gedf,
                                  double dw_over_da_gedf
                                  ) {

  return background_gedf_ca2_from_params(
                                          pba->s_a_gedf,
                                          pba->wi_edf,
                                          pba->wf_edf,
                                          a,
                                          w_gedf,
                                          dw_over_da_gedf
                                          );
}

static double background_gedf_2_ca2(
                                    struct background * pba,
                                    double a,
                                    double w_gedf,
                                    double dw_over_da_gedf
                                    ) {

  return background_gedf_ca2_from_params(
                                          pba->s_a_gedf_2,
                                          pba->wi_gedf_2,
                                          pba->wf_gedf_2,
                                          a,
                                          w_gedf,
                                          dw_over_da_gedf
                                          );
}

/**
 * Background quantities at given redshift z.
 *
 * Evaluates all background quantities at a given value of
 * redshift by reading the pre-computed table and interpolating.
 *
 * @param pba           Input: pointer to background structure (containing pre-computed table)
 * @param z             Input: redshift
//       with a=a_ini. If your w(a) does not lead to a simple analytic
//       solution of this integral, no worry: instead of writing
//       something here, the best would then be to leave it equal to
//       zero, and then in background_initial_conditions() you should
//       implement a numerical calculation of this integral only for
//       a=a_ini, using for instance Romberg integration. It should be
//       fast, simple, and accurate enough. */
//   // switch (pba->fluid_equation_of_state) {
//     *integral_drdm = 0.;
//   // }

//   /** note: of course you can generalise these formulas to anything,
//       defining new parameters pba->w..._fld. Just remember that so
//       far, HyRec explicitely assumes that w(a)= w0 + wa (1-a/a0); but
//       Recfast does not assume anything */

//   return _SUCCESS_;
// }

int background_w_gedf(
                     struct background * pba,
                     double a,
                     double * w_edf,
                     double * dw_over_da_edf,
                     double * integral_edf
                     ){
  double wi, wf, A, B;
  double y, f, exp_y;
  double logacB, logaB;
  double M, log_1_plus_acB, log_aB_plus_acB;

  wi = pba->wi_edf;
  wf = pba->wf_edf;
  A = - wi + wf;
  B = pba->s_a_gedf * (1. + wf);

  /* w(a) = (-wi + wf)/(1 + (ac/a)^(s_a(1+wf))) + wi */
  if (fabs(B) < 1e-14) {
    *w_edf = 0.5 * A + wi;
    *dw_over_da_edf = 0.;
    *integral_edf = 3. * (1. + *w_edf) * log(1./a);
    return _SUCCESS_;
  }

  y = B * (log(pba->ac_gedf) - log(a));
  if (y >= 0.) {
    exp_y = exp(-y);
    f = exp_y/(1. + exp_y);
  }
  else {
    exp_y = exp(y);
    f = 1./(1. + exp_y);
  }

  *w_edf = A * f + wi;
  *dw_over_da_edf = A * B * f * (1. - f) / a;

  logacB = B * log(pba->ac_gedf);
  logaB = B * log(a);
  if (logacB >= 0.) {
    log_1_plus_acB = logacB + log1p(exp(-logacB));
  }
  else {
    log_1_plus_acB = log1p(exp(logacB));
  }
  M = (logaB > logacB) ? logaB : logacB;
  log_aB_plus_acB = M + log(exp(logaB - M) + exp(logacB - M));

  *integral_edf = 3. * (1. + wi) * log(1./a) + (3. * A / B) * (log_1_plus_acB - log_aB_plus_acB);

  return _SUCCESS_;
}

int background_w_gedf_2(
                     struct background * pba,
                     double a,
                     double * w_edf,
                     double * dw_over_da_edf,
                     double * integral_edf
                     ){
  double wi, wf, A, B;
  double y, f, exp_y;
  double logacB, logaB;
  double M, log_1_plus_acB, log_aB_plus_acB;

  wi = pba->wi_gedf_2;
  wf = pba->wf_gedf_2;
  A = - wi + wf;
  B = pba->s_a_gedf_2 * (1. + wf);

  /* w(a) = (-wi + wf)/(1 + (ac/a)^(s_a(1+wf))) + wi */
  if (fabs(B) < 1e-14) {
    *w_edf = 0.5 * A + wi;
    *dw_over_da_edf = 0.;
    *integral_edf = 3. * (1. + *w_edf) * log(1./a);
    return _SUCCESS_;
  }

  y = B * (log(pba->ac_gedf_2) - log(a));
  if (y >= 0.) {
    exp_y = exp(-y);
    f = exp_y/(1. + exp_y);
  }
  else {
    exp_y = exp(y);
    f = 1./(1. + exp_y);
  }

  *w_edf = A * f + wi;
  *dw_over_da_edf = A * B * f * (1. - f) / a;
  // *dw_over_da_edf = -1.* A * B * pow(f,2) * (1. - 1./f) / a;

  logacB = B * log(pba->ac_gedf_2);
  logaB = B * log(a);
  if (logacB >= 0.) {
    log_1_plus_acB = logacB + log1p(exp(-logacB));
  }
  else {
    log_1_plus_acB = log1p(exp(logacB));
  }
  M = (logaB > logacB) ? logaB : logacB;
  log_aB_plus_acB = M + log(exp(logaB - M) + exp(logacB - M));

  *integral_edf = 3. * (1. + wi) * log(1./a) + (3. * A / B) * (log_1_plus_acB - log_aB_plus_acB);

  return _SUCCESS_;
}

