/** @file perturbations.c Documented perturbation module
 *
 * Julien Lesgourgues, 23.09.2010
 *
 * Deals with the perturbation evolution.
 * This module has two purposes:
 *
 * - at the beginning; to initialize the perturbations, i.e. to
 * integrate the perturbation equations, and store temporarily the terms
 * contributing to the source functions as a function of conformal
 * time. Then, to perform a few manipulations of these terms in order to
 * infer the actual source functions \f$ S^{X} (k, \tau) \f$, and to
 * store them as a function of conformal time inside an interpolation
 * table.
 *
 * - at any time in the code; to evaluate the source functions at a
 * given conformal time (by interpolating within the interpolation
 * table).
 *
 * Hence the following functions can be called from other modules:
 *
 * -# perturbations_init() at the beginning (but after background_init() and thermodynamics_init())
 * -# perturbations_sources_at_tau() at any later time
 * -# perturbations_free() at the end, when no more calls to perturbations_sources_at_tau() are needed
 */

#include "perturbations.h"
#include "parallel.h"

static void perturbations_gedf_sound_speeds(
                                            struct background * pba,
                                            double a,
                                            double w_gedf,
                                            double dw_over_da_gedf,
                                            double * ca2_gedf,
                                            double * cs2_gedf
                                            ) {

  double one_plus_w = 1. + w_gedf;
  double B = (pba->use_exp_gedf == _TRUE_) ?
    pba->q_gedf : pba->s_a_gedf * (1. + pba->wf_edf);
  double log_t, t, exp_minus_t, transition_fraction;

  *cs2_gedf = (a <= pba->ac_gedf) ? 1. : pba->wf_edf;

  if ((pba->use_exp_gedf == _TRUE_)
      && (fabs(1. + pba->wi_edf) < 1.e-10)) {
    log_t = log(log(2.)) + pba->q_gedf * (log(a) - log(pba->ac_gedf));
    if (log_t > log(-log(DBL_MIN))) {
      *ca2_gedf = w_gedf;
    }
    else {
      t = exp(log_t);
      exp_minus_t = exp(-t);
      transition_fraction = -expm1(-t);
      if (transition_fraction > 0.) {
        *ca2_gedf = w_gedf - pba->q_gedf * t * exp_minus_t
          / (3. * transition_fraction);
      }
      else {
        *ca2_gedf = pba->wi_edf - pba->q_gedf / 3.;
      }
    }
  }
  else if (fabs(one_plus_w) > 1.e-10) {
    *ca2_gedf = w_gedf - a * dw_over_da_gedf / 3. / one_plus_w;
  }
  else if (fabs(1. + pba->wi_edf) < 1.e-10) {
    *ca2_gedf = pba->wi_edf - B / 3.;
  }
  else {
    *ca2_gedf = w_gedf;
  }
}

static void perturbations_gedf_2_sound_speeds(
                                              struct background * pba,
                                              double a,
                                              double w_gedf,
                                              double dw_over_da_gedf,
                                              double * ca2_gedf,
                                              double * cs2_gedf
                                              ) {

  double one_plus_w = 1. + w_gedf;
  double B = pba->s_a_gedf_2 * (1. + pba->wf_gedf_2);

  *cs2_gedf = (a <= pba->ac_gedf_2) ? 1. : pba->wf_gedf_2;

  if (fabs(one_plus_w) > 1.e-10) {
    *ca2_gedf = w_gedf - a * dw_over_da_gedf / 3. / one_plus_w;
  }
  else if (fabs(1. + pba->wi_gedf_2) < 1.e-10) {
    *ca2_gedf = pba->wi_gedf_2 - B / 3.;
  }
  else {
    *ca2_gedf = w_gedf;
  }
}


