          && ((index_target == f_gedf) || (index_target == f_gedf_2)))
        continue;
      /* input_needs_shoting_for_target takes care of the case where, for
         instance, Omega_dcdmdr is set to 0.0, and we don't need shooting */
      class_call(input_needs_shooting_for_target(pfc,
                                                 index_target,
                                                 param1,
                                                 &needs_shooting,
                                                 errmsg),
                 errmsg,
                 errmsg);

      if (needs_shooting == _TRUE_){
        target_indices[unknown_parameters_size] = index_target;
        fzw.required_computation_stage = MAX(fzw.required_computation_stage,target_cs[index_target]);
        unknown_parameters_size++;
      }

    }
  }

  /** In the case of unknown parameters, start shooting... */
  if (unknown_parameters_size > 0) {

    /* We need to remember that we shot so we can clean up properly */
    *has_shooting=_TRUE_;

    /* Create file content structure with additional entries */
    class_call(parser_extend(pfc, unknown_parameters_size, errmsg),
               errmsg,errmsg);

    class_call(parser_init_from_pfc(pfc, &(fzw.fc), errmsg),
               errmsg,errmsg);

    class_alloc(unknown_parameter,
                unknown_parameters_size*sizeof(double),
                errmsg);
    class_alloc(fzw.unknown_parameters_index,
                unknown_parameters_size*sizeof(int),
                errmsg);

    fzw.target_size = unknown_parameters_size;
    class_alloc(fzw.target_name,
                fzw.target_size*sizeof(enum target_names),
                errmsg);
    class_alloc(fzw.target_value,
                fzw.target_size*sizeof(double),
                errmsg);

    /** Go through all cases with unknown parameters */
    for (counter = 0; counter < unknown_parameters_size; counter++){
      index_target = target_indices[counter];
      class_call(parser_read_double(pfc,
                                    target_namestrings[index_target],
                                    &param1,
                                    &flag1,
                                    errmsg),
                 errmsg,
                 errmsg);

      /* store name of target parameter */
      fzw.target_name[counter] = index_target;
      /* store target value of target parameter */
      fzw.target_value[counter] = param1;
      fzw.unknown_parameters_index[counter]=pfc->size+counter-unknown_parameters_size;
      /* substitute the name of the target parameter with the name of the
         corresponding unknown parameter */
      strcpy(fzw.fc.name[fzw.unknown_parameters_index[counter]],unknown_namestrings[index_target]);
    }

    /** If there is only one parameter, we use a more efficient Newton method for 1D cases */
    if (unknown_parameters_size == 1){

      /* We can do 1 dimensional root finding */
      if (input_verbose > 0) {
        printf("Computing unknown input parameter '%s' using input parameter '%s'\n",
               fzw.fc.name[fzw.unknown_parameters_index[0]],
               target_namestrings[fzw.target_name[0]]);
      }

      /* If shooting fails, postpone error to background module to play nice with MontePython. */
      class_call_try(input_find_root(&xzero,
                                     &fevals,
                                     ppr->tol_shooting_deltax_rel,
                                     &fzw,
                                     errmsg),
                     errmsg,
                     pba->shooting_error,
                     shooting_failed=_TRUE_);

      /* Store xzero */
      // This needs to be done with enough accuracy. A standard double has a relative
      // precision of around 1e-16, so 1e-20 should be good enough for the shooting
      class_sprintf(fzw.fc.value[fzw.unknown_parameters_index[0]],"%.20e",xzero);
      if (input_verbose > 0) {
        if (shooting_failed == _FALSE_){
          printf(" -> found '%s = %s'\n",
                  fzw.fc.name[fzw.unknown_parameters_index[0]],
                  fzw.fc.value[fzw.unknown_parameters_index[0]]);
        }
        else{
          printf("Shooting failed! Aborting...\n");
        }
      }

    }
    /** Otherwise we do multidimensional shooting */
    else{

      /* We need to do multidimensional root finding */
      if (input_verbose > 0) {
        printf("Computing unknown input parameters\n");
      }

      /* Allocate local variables */
      class_alloc(x_inout,
                  sizeof(double)*unknown_parameters_size,
                  errmsg);
      class_alloc(dxdF,
                  sizeof(double)*unknown_parameters_size,
                  errmsg);

      /* Get the guess for the initial variables */
      class_call(input_get_guess(x_inout, dxdF, &fzw, errmsg),
                 errmsg,
                 errmsg);

      /* Use multi-dimensional Newton method */
      class_call_try(fzero_Newton(input_try_unknown_parameters,
                                  x_inout,
                                  dxdF,
                                  unknown_parameters_size,
                                  ppr->tol_shooting_deltax,
                                  ppr->tol_shooting_deltaF,
                                  &fzw,
                                  &fevals,
                                  errmsg),
                     errmsg,
                     pba->shooting_error,
                     shooting_failed=_TRUE_);

      /* Store xzero */
      // This needs to be done with enough accuracy. A standard double has a relative
      // precision of around 1e-16, so 1e-20 should be good enough for the shooting
      for (counter = 0; counter < unknown_parameters_size; counter++){
        class_sprintf(fzw.fc.value[fzw.unknown_parameters_index[counter]],
                "%.20e",x_inout[counter]);
        if (input_verbose > 0) {
          if (shooting_failed == _FALSE_){
            printf(" -> found '%s = %s'\n",
                    fzw.fc.name[fzw.unknown_parameters_index[counter]],
                    fzw.fc.value[fzw.unknown_parameters_index[counter]]);
          }
          else{
            printf("Shooting failed! Aborting...\n");
          }
        }
      }

      /* Free local variables */
      free(x_inout);
      free(dxdF);
    }

    if (input_verbose > 1 && shooting_failed == _FALSE_) {
      printf("Shooting completed using %d function evaluations\n",fevals);
    }

    /** Set status of shooting */
    pba->shooting_failed = shooting_failed;

    parser_copy(&(fzw.fc), pfc, pfc->size - unknown_parameters_size, pfc->size);

    /** Free arrays allocated */
    class_call(parser_free(&(fzw.fc)),
               errmsg, errmsg);
    free(unknown_parameter);
    free(fzw.unknown_parameters_index);
    free(fzw.target_name);
    free(fzw.target_value);
  }

  /** With H0 fixed, shoot the two GEDF fractions independently in 1D. */
  if (separate_gedf_shooting == _TRUE_) {
    enum target_names gedf_target_names[] = {f_gedf, f_gedf_2};
    char * gedf_target_namestrings[] = {"f_gedf", "f_gedf_2"};
    char * gedf_unknown_namestrings[] = {"rho_gedf", "rho_gedf_2"};
    double gedf_target_values[] = {f_gedf_target, f_gedf_2_target};
    int gedf_target_flags[] = {has_f_gedf_target, has_f_gedf_2_target};
    int gedf_unknown_indices[] = {-1, -1};
    int gedf_active[] = {_FALSE_, _FALSE_};
    int gedf_index, gedf_iteration;
    int gedf_active_count = 0;
    int gedf_converged = _FALSE_;
    double max_relative_change;

    for (gedf_index = 0; gedf_index < 2; gedf_index++) {
      if (gedf_target_flags[gedf_index] == _FALSE_)
        continue;

      class_call(input_needs_shooting_for_target(pfc,
                                                 gedf_target_names[gedf_index],
                                                 gedf_target_values[gedf_index],
                                                 &needs_shooting,
                                                 errmsg),
                 errmsg,
                 errmsg);
      if (needs_shooting == _FALSE_)
        continue;

      gedf_active[gedf_index] = _TRUE_;
      gedf_active_count++;
    }

    for (gedf_iteration = 0;
         (gedf_iteration < 12) && (gedf_converged == _FALSE_) && (shooting_failed == _FALSE_);
         gedf_iteration++) {
      max_relative_change = 0.;

      for (gedf_index = 0; gedf_index < 2; gedf_index++) {
        FileArg swap_name, swap_value;
        short swap_read;
        double previous_x;
        int last_index;

        if (gedf_active[gedf_index] == _FALSE_)
          continue;

        *has_shooting = _TRUE_;
        if (gedf_unknown_indices[gedf_index] < 0) {
          class_call(parser_extend(pfc, 1, errmsg),
                     errmsg,
                     errmsg);
          gedf_unknown_indices[gedf_index] = pfc->size - 1;
          strcpy(pfc->name[gedf_unknown_indices[gedf_index]],
                 gedf_unknown_namestrings[gedf_index]);
          pfc->value[gedf_unknown_indices[gedf_index]][0] = '\0';
        }
        previous_x = atof(pfc->value[gedf_unknown_indices[gedf_index]]);

        class_call(parser_init_from_pfc(pfc, &(fzw.fc), errmsg),
                   errmsg,
                   errmsg);

        /* input_get_guess() expects the one unknown entry to be last, since it
           temporarily hides the final target_size entries while reading the
           known parameters. Move the density being shot to that position in
           the private file-content copy; the original ordering is unchanged. */
        last_index = fzw.fc.size - 1;
        if (gedf_unknown_indices[gedf_index] != last_index) {
          strcpy(swap_name, fzw.fc.name[last_index]);
          strcpy(swap_value, fzw.fc.value[last_index]);
          swap_read = fzw.fc.read[last_index];
          strcpy(fzw.fc.name[last_index], fzw.fc.name[gedf_unknown_indices[gedf_index]]);
          strcpy(fzw.fc.value[last_index], fzw.fc.value[gedf_unknown_indices[gedf_index]]);
          fzw.fc.read[last_index] = fzw.fc.read[gedf_unknown_indices[gedf_index]];
          strcpy(fzw.fc.name[gedf_unknown_indices[gedf_index]], swap_name);
          strcpy(fzw.fc.value[gedf_unknown_indices[gedf_index]], swap_value);
          fzw.fc.read[gedf_unknown_indices[gedf_index]] = swap_read;
        }

        fzw.target_size = 1;
        fzw.required_computation_stage = cs_background;
        class_alloc(fzw.unknown_parameters_index, sizeof(int), errmsg);
        class_alloc(fzw.target_name, sizeof(enum target_names), errmsg);
        class_alloc(fzw.target_value, sizeof(double), errmsg);

        fzw.unknown_parameters_index[0] = last_index;
        fzw.target_name[0] = gedf_target_names[gedf_index];
        fzw.target_value[0] = gedf_target_values[gedf_index];

        if (input_verbose > 0) {
          printf("Computing unknown input parameter '%s' using input parameter '%s' (separate H0 shooting, pass %d)\n",
                 gedf_unknown_namestrings[gedf_index],
                 gedf_target_namestrings[gedf_index],
                 gedf_iteration + 1);
        }

        xzero = previous_x;
        class_call_try(input_find_root(&xzero,
                                       &fevals,
                                       ppr->tol_shooting_deltax_rel,
                                       &fzw,
                                       errmsg),
                       errmsg,
                       pba->shooting_error,
                       shooting_failed=_TRUE_);

        class_sprintf(pfc->value[gedf_unknown_indices[gedf_index]],"%.20e",xzero);
        max_relative_change = MAX(max_relative_change,
                                  fabs(xzero-previous_x)/MAX(fabs(xzero),1.));
        if ((input_verbose > 0) && (shooting_failed == _FALSE_)) {
          printf(" -> found '%s = %s'\n",
                 gedf_unknown_namestrings[gedf_index],
                 pfc->value[gedf_unknown_indices[gedf_index]]);
        }

        class_call(parser_free(&(fzw.fc)), errmsg, errmsg);
        free(fzw.unknown_parameters_index);
        free(fzw.target_name);
        free(fzw.target_value);

        if (shooting_failed == _TRUE_)
          break;
      }

      if ((gedf_active_count < 2)
          || (max_relative_change < ppr->tol_shooting_deltax_rel))
        gedf_converged = _TRUE_;
    }

    if ((shooting_failed == _FALSE_) && (gedf_converged == _FALSE_)) {
      class_sprintf(pba->shooting_error,
                    "Separate H0 shooting of f_gedf and f_gedf_2 did not converge after %d passes.",
                    gedf_iteration);
      shooting_failed = _TRUE_;
    }
    if ((input_verbose > 1) && (shooting_failed == _FALSE_))
      printf("Separate H0 GEDF shooting converged in %d passes using %d function evaluations\n",
             gedf_iteration,
             fevals);
    pba->shooting_failed = shooting_failed;
  }


  /** After the 'normal' shooting is done, do special shooting just for sigma8 if needed*/
  class_call(parser_read_double(pfc,"sigma8",&param1,&flag1,errmsg),
             errmsg,
             errmsg);
  class_call(parser_read_double(pfc,"S8",&param2,&flag2,errmsg),
             errmsg,
             errmsg);
  class_test((flag1 == _TRUE_) && (flag2 == _TRUE_),
             errmsg,
             "You can only enter one of 'sigma8' or 'S8'.");
  if (flag1 == _TRUE_ || flag2 == _TRUE_) {
    /* Tell the main function that shooting indeed has occured */
    *has_shooting=_TRUE_;

    /* Create file content structure with additional entries */
    class_call(parser_extend(pfc, 1, errmsg),
               errmsg,errmsg);

    class_call(parser_init_from_pfc(pfc, &(fzw.fc), errmsg),
               errmsg,errmsg);

    fzw.target_size = 1;
    class_alloc(fzw.unknown_parameters_index,
                1*sizeof(int),
                errmsg);
    class_alloc(fzw.target_name,
                1*sizeof(enum target_names),
                errmsg);
    class_alloc(fzw.target_value,
                1*sizeof(double),
                errmsg);

    /* store name of target parameter */
    if (flag1 == _TRUE_) {
      fzw.target_name[0] = sigma8;
      fzw.target_value[0] = param1;
    }
    else if (flag2 == _TRUE_) {
      fzw.target_name[0] = S8;
      fzw.target_value[0] = param2;
    }
  }

  else {
    if (fl == 0.0) return x1;
    if (fh == 0.0) return x2;
    class_stop(error_message,"root must be bracketed in zriddr.");
  }
  class_stop(error_message,"Failure in int.");
}


/**
 * Related to 'shooting': we define here a reasonable analytic guess
 * for each unknown parameter as a function of its target
 * parameter. We must also estimate dxdy, i.e. how the unknown
 * parameter responds to the target parameter.  This can simply be
 * estimated as the derivative of the guess formula.
 *
 * @param xguess Output: guess for unkown parameter x given target parameter y
 * @param dxdy   Output: guess for derivative dx/dy
 * @param pfzw   Input : pointer to workspace containing targets, unkown parameters and other relevant information
 * @param errmsg Input/Output: Error message
 * @return the error status
 */

int input_get_guess(double *xguess,
                    double *dxdy,
                    struct fzerofun_workspace * pfzw,
                    ErrorMsg errmsg){

  /** Summary: */

  /** Define local variables */
  struct precision pr;        /* for precision parameters */
  struct background ba;       /* for cosmological background */
  struct thermodynamics th;           /* for thermodynamics */
  struct perturbations pt;         /* for source functions */
  struct transfer tr;        /* for transfer functions */
  struct primordial pm;       /* for primordial spectra */
  struct harmonic hr;          /* for output spectra */
  struct fourier fo;        /* for non-linear spectra */
  struct lensing le;          /* for lensed spectra */
  struct distortions sd;      /* for spectral distortions */
  struct output op;           /* for output files */
  int i;
  double Omega_M, a_decay, gamma, Omega0_dcdmdr=1.0;
  double rho_no_gedf, Omega_r, Omega_m;
  int index_guess;
  int index_ncdm; double N_nonur_guess = 0.0;
  int index_f_gedf = -1, index_f_gedf_2 = -1;
  double rho_no_gedf_1 = 0., rho_no_gedf_2 = 0.;
  double k_gedf = 0., k_gedf_2 = 0.;
  double integral_gedf_ac1 = 0., integral_gedf_ac2 = 0.;
  double integral_gedf2_ac1 = 0., integral_gedf2_ac2 = 0.;
  double w_tmp, dw_tmp, det;

  /* Cheat to read only known parameters: */
  pfzw->fc.size -= pfzw->target_size;

  /* Assume for now shooting did not fail */
  ba.shooting_failed = _FALSE_;

  class_call(input_read_precisions(&(pfzw->fc),&pr,&ba,&th,&pt,&tr,&pm,&hr,&fo,&le,&sd,&op,
                                   errmsg),
             errmsg,
             errmsg);
  class_call(input_read_parameters(&(pfzw->fc),&pr,&ba,&th,&pt,&tr,&pm,&hr,&fo,&le,&sd,&op,
                                   errmsg),
             errmsg,
             errmsg);

  pfzw->fc.size += pfzw->target_size;

  /** Estimate dxdy */
  for (index_guess=0; index_guess < pfzw->target_size; index_guess++) {
    switch (pfzw->target_name[index_guess]) {
    case theta_s:
    case theta_s_100:
      xguess[index_guess] = 3.54*pow(pfzw->target_value[index_guess],2)-5.455*pfzw->target_value[index_guess]+2.548;
      dxdy[index_guess] = (7.08*pfzw->target_value[index_guess]-5.455);
      /** Update pb to reflect guess */
      ba.h = xguess[index_guess];
      ba.H0 = ba.h *  1.e5 / _c_;
      // printf(" Shooting guess of h = %-15g, \n", xguess[index_guess]);
      break;
    case Neff:
      for(index_ncdm=0;index_ncdm<ba.N_ncdm;++index_ncdm){
        N_nonur_guess += ba.deg_ncdm[index_ncdm]* 1.0132;
      }
      N_nonur_guess += ba.Omega0_idr/ba.Omega0_g/(7./8.)*pow(11./4.,(4./3.));
      xguess[index_guess] = pfzw->target_value[index_guess] - N_nonur_guess;
      dxdy[index_guess] = 1.;
      break;
    case Omega_dcdmdr:
      Omega_M = ba.Omega0_cdm+ba.Omega0_idm+ba.Omega0_dcdmdr+ba.Omega0_b;
      /* *
       * This formula is exact in a Matter + Lambda Universe, but only for Omega_dcdm,
       * not the combined.
       * sqrt_one_minus_M = sqrt(1.0 - Omega_M);
       * xguess[index_guess] = pfzw->target_value[index_guess]*
       *                       exp(2./3.*ba.Gamma_dcdm/ba.H0*
       *                       atanh(sqrt_one_minus_M)/sqrt_one_minus_M);
       * dxdy[index_guess] = 1.0;//exp(2./3.*ba.Gamma_dcdm/ba.H0*atanh(sqrt_one_minus_M)/sqrt_one_minus_M);
       * */
      gamma = ba.Gamma_dcdm/ba.H0;
      if (gamma < 1)
        a_decay = 1.0;
      else
        a_decay = pow(1+(gamma*gamma-1.)/Omega_M,-1./3.);
      xguess[index_guess] = pfzw->target_value[index_guess]/a_decay;
      dxdy[index_guess] = 1./a_decay;
      break;
    case omega_dcdmdr:
      Omega_M = ba.Omega0_cdm+ba.Omega0_idm+ba.Omega0_dcdmdr+ba.Omega0_b;
      gamma = ba.Gamma_dcdm/ba.H0;
      if (gamma < 1)
        a_decay = 1.0;
      else
        a_decay = pow(1+(gamma*gamma-1.)/Omega_M,-1./3.);
      xguess[index_guess] = pfzw->target_value[index_guess]/ba.h/ba.h/a_decay;
      dxdy[index_guess] = 1./a_decay/ba.h/ba.h;
      break;
    case Omega_scf:
      /* *
       * This guess is arbitrary, something nice using WKB should be implemented.
       * Version 2 uses a fit
       * xguess[index_guess] = 1.77835*pow(ba.Omega0_scf,-2./7.);
       * dxdy[index_guess] = -0.5081*pow(ba.Omega0_scf,-9./7.)`;
       * Version 3: use attractor solution
       * */
      if (ba.scf_tuning_index == 0){
        xguess[index_guess] = sqrt(3.0/ba.Omega0_scf);
        dxdy[index_guess] = -0.5*sqrt(3.0)*pow(ba.Omega0_scf,-1.5);
      }
      else{
        /* Default: take the passed value as xguess and set dxdy to 1. */
        xguess[index_guess] = ba.scf_parameters[ba.scf_tuning_index];
        dxdy[index_guess] = 1.;
      }
      break;
    case omega_ini_dcdm:
      Omega0_dcdmdr = 1./(ba.h*ba.h);
    case Omega_ini_dcdm:
      /* This works since correspondence is Omega_ini_dcdm -> Omega_dcdmdr and
         omega_ini_dcdm -> omega_dcdmdr */
      Omega0_dcdmdr *=pfzw->target_value[index_guess];
      Omega_M = ba.Omega0_cdm+ba.Omega0_idm+Omega0_dcdmdr+ba.Omega0_b;
      gamma = ba.Gamma_dcdm/ba.H0;
      if (gamma < 1)
        a_decay = 1.0;
      else
        a_decay = pow(1+(gamma*gamma-1.)/Omega_M,-1./3.);
      xguess[index_guess] = pfzw->target_value[index_guess]*a_decay;
      dxdy[index_guess] = a_decay;
      if (gamma > 100)
        dxdy[index_guess] *= gamma/100;
      break;
    case f_gedf:
      class_test((pfzw->target_value[index_guess] < 0.) || (pfzw->target_value[index_guess] >= 1.),
                 errmsg,
                 "The requested value of 'f_gedf' must be in the interval [0,1), not %g.",
                 pfzw->target_value[index_guess]);
      Omega_r = ba.Omega0_g + ba.Omega0_ur + ba.Omega0_idr;
      Omega_m = ba.Omega0_b + ba.Omega0_cdm + ba.Omega0_idm + ba.Omega0_dcdmdr;
      rho_no_gedf = pow(ba.H0,2) * (Omega_r/pow(ba.ac_gedf,4)
                                    + Omega_m/pow(ba.ac_gedf,3)
                                    + ba.Omega0_lambda
                                    + ba.Omega0_fld);
      rho_no_gedf_1 = rho_no_gedf;
      k_gedf = pfzw->target_value[index_guess] / (1. - pfzw->target_value[index_guess]);
      xguess[index_guess] = pfzw->target_value[index_guess] * rho_no_gedf
        / (1. - pfzw->target_value[index_guess]);
      dxdy[index_guess] = rho_no_gedf
        / pow(1. - pfzw->target_value[index_guess],2);
      index_f_gedf = index_guess;
      break;
    case f_gedf_2:
      class_test((pfzw->target_value[index_guess] < 0.) || (pfzw->target_value[index_guess] >= 1.),
                 errmsg,
                 "The requested value of 'f_gedf_2' must be in the interval [0,1), not %g.",
                 pfzw->target_value[index_guess]);
      Omega_r = ba.Omega0_g + ba.Omega0_ur + ba.Omega0_idr;
      Omega_m = ba.Omega0_b + ba.Omega0_cdm + ba.Omega0_idm + ba.Omega0_dcdmdr;
      rho_no_gedf = pow(ba.H0,2) * (Omega_r/pow(ba.ac_gedf_2,4)
                                    + Omega_m/pow(ba.ac_gedf_2,3)
                                    + ba.Omega0_lambda
                                    + ba.Omega0_fld);
      rho_no_gedf_2 = rho_no_gedf;
      k_gedf_2 = pfzw->target_value[index_guess] / (1. - pfzw->target_value[index_guess]);
      xguess[index_guess] = pfzw->target_value[index_guess] * rho_no_gedf
        / (1. - pfzw->target_value[index_guess]);
      dxdy[index_guess] = rho_no_gedf
        / pow(1. - pfzw->target_value[index_guess],2);
      index_f_gedf_2 = index_guess;
      break;

    case sigma8:
      /* Assume linear relationship between A_s and sigma8 and fix coefficient
         according to vanilla LambdaCDM. Should be good enough... */
      xguess[index_guess] = 2.43e-9/0.87659*pfzw->target_value[index_guess];
      dxdy[index_guess] = 2.43e-9/0.87659;
      break;
    case S8:
      /* Assume linear relationship between A_s and S8 and fix coefficient
         according to vanilla LambdaCDM. Should be good enough... */
      xguess[index_guess] = 2.43e-9/0.891*pfzw->target_value[index_guess];
      dxdy[index_guess] = 2.43e-9/0.891;
      break;
    }
  }

  if ((index_f_gedf >= 0) && (index_f_gedf_2 >= 0)) {
    class_call(background_w_gedf(&ba,ba.ac_gedf,&w_tmp,&dw_tmp,&integral_gedf_ac1),
               ba.error_message,
               errmsg);
    class_call(background_w_gedf(&ba,ba.ac_gedf_2,&w_tmp,&dw_tmp,&integral_gedf_ac2),
               ba.error_message,
               errmsg);
