#include "background.h"
#include <gsl/gsl_integration.h>

static double background_gedf_ca2_from_params(
                                              double s_a_gedf,
                                              double wi_gedf,
                                              double wf_gedf,
                                              double a,
                                              double w_gedf,
                                              double dw_over_da_gedf
                                              ) {

  double one_plus_w = 1. + w_gedf;
  double B = s_a_gedf * (1. + wf_gedf);

  if (fabs(one_plus_w) > 1.e-10) {
    return w_gedf - a * dw_over_da_gedf / 3. / one_plus_w;
  }
  if (fabs(1. + wi_gedf) < 1.e-10) {
    return wi_gedf - B / 3.;
  }
  return w_gedf;
}

static double background_gedf_ca2(
                                  struct background * pba,
                                  double a,
                                  double w_gedf,
                                  double dw_over_da_gedf
                                  ) {

  return background_gedf_ca2_from_params(
                                          pba->s_a_gedf,
                                          pba->wi_edf,
                                          pba->wf_edf,
                                          a,
                                          w_gedf,
                                          dw_over_da_gedf
                                          );
}

static double background_gedf_2_ca2(
                                    struct background * pba,
                                    double a,
                                    double w_gedf,
                                    double dw_over_da_gedf
                                    ) {

  return background_gedf_ca2_from_params(
                                          pba->s_a_gedf_2,
                                          pba->wi_gedf_2,
                                          pba->wf_gedf_2,
                                          a,
                                          w_gedf,
                                          dw_over_da_gedf
                                          );
}

/**
 * Background quantities at given redshift z.
 *
 * Evaluates all background quantities at a given value of
 * redshift by reading the pre-computed table and interpolating.
 *
 * @param pba           Input: pointer to background structure (containing pre-computed table)
 * @param z             Input: redshift
 * @param return_format Input: format of output vector (short_info, normal_info, long_info)
 * @param inter_mode     Input: interpolation mode (normal or closeby)
 * @param last_index    Input/Output: index of the previous/current point in the interpolation array (input only for closeby mode, output for both)
 * @param pvecback      Output: vector (assumed to be already allocated)
 * @return the error status
 */

int background_at_z(
                    struct background *pba,
                    double z,
                    enum vecback_format return_format,
                    enum interpolation_method inter_mode,
                    int * last_index,
                    double * pvecback /* vector with argument pvecback[index_bg] (must be already allocated with a size compatible with return_format) */
                    ) {

  /** Summary: */

  /** - define local variables */

  /* size of output vector, controlled by input parameter return_format */
  int pvecback_size;

  /* log(a) (in fact, given our normalisation conventions, this is log(a/a_0)) */
  double loga;

  /** - check that log(a) = log(1/(1+z)) = -log(1+z) is in the pre-computed range */
  loga = -log(1+z);

  class_test(loga < pba->loga_table[0],
                     struct background * pba,
                     double a,
                     double * w_edf,
                     double * dw_over_da_edf,
                     double * integral_edf
                     ){
  double wi, wf, A, B;
  double y, f, exp_y;
  double logacB, logaB;
  double M, log_1_plus_acB, log_aB_plus_acB;

  wi = pba->wi_edf;
  wf = pba->wf_edf;
  A = - wi + wf;
  B = pba->s_a_gedf * (1. + wf);

  /* w(a) = (-wi + wf)/(1 + (ac/a)^(s_a(1+wf))) + wi */
  if (fabs(B) < 1e-14) {
    *w_edf = 0.5 * A + wi;
    *dw_over_da_edf = 0.;
    *integral_edf = 3. * (1. + *w_edf) * log(1./a);
    return _SUCCESS_;
  }

  y = B * (log(pba->ac_gedf) - log(a));
  if (y >= 0.) {
    exp_y = exp(-y);
    f = exp_y/(1. + exp_y);
  }
  else {
    exp_y = exp(y);
    f = 1./(1. + exp_y);
  }

  *w_edf = A * f + wi;
  *dw_over_da_edf = A * B * f * (1. - f) / a;

  logacB = B * log(pba->ac_gedf);
  logaB = B * log(a);
  if (logacB >= 0.) {
    log_1_plus_acB = logacB + log1p(exp(-logacB));
  }
  else {
    log_1_plus_acB = log1p(exp(logacB));
  }
  M = (logaB > logacB) ? logaB : logacB;
  log_aB_plus_acB = M + log(exp(logaB - M) + exp(logacB - M));

  *integral_edf = 3. * (1. + wi) * log(1./a) + (3. * A / B) * (log_1_plus_acB - log_aB_plus_acB);

  return _SUCCESS_;
}

int background_w_gedf_2(
                     struct background * pba,
                     double a,
                     double * w_edf,
                     double * dw_over_da_edf,
                     double * integral_edf
                     ){
  double wi, wf, A, B;
  double y, f, exp_y;
  double logacB, logaB;
  double M, log_1_plus_acB, log_aB_plus_acB;

  wi = pba->wi_gedf_2;
  wf = pba->wf_gedf_2;
  A = - wi + wf;
  B = pba->s_a_gedf_2 * (1. + wf);

  /* w(a) = (-wi + wf)/(1 + (ac/a)^(s_a(1+wf))) + wi */
  if (fabs(B) < 1e-14) {
    *w_edf = 0.5 * A + wi;
    *dw_over_da_edf = 0.;
    *integral_edf = 3. * (1. + *w_edf) * log(1./a);
    return _SUCCESS_;
  }

  y = B * (log(pba->ac_gedf_2) - log(a));
  if (y >= 0.) {
    exp_y = exp(-y);
    f = exp_y/(1. + exp_y);
  }
  else {
    exp_y = exp(y);
    f = 1./(1. + exp_y);
  }

  *w_edf = A * f + wi;
  *dw_over_da_edf = A * B * f * (1. - f) / a;
  // *dw_over_da_edf = -1.* A * B * pow(f,2) * (1. - 1./f) / a;

  logacB = B * log(pba->ac_gedf_2);
  logaB = B * log(a);
  if (logacB >= 0.) {
    log_1_plus_acB = logacB + log1p(exp(-logacB));
  }
  else {
    log_1_plus_acB = log1p(exp(logacB));
  }
