      ppw->ca2_gedf_output = ca2_gedf;
      ppw->cs2_gedf_output = cs2_gedf;
      ppw->u_gedf = y[ppw->pv->index_pt_u_gedf];

      ppw->delta_rho += ppw->delta_rho_gedf;
      ppw->rho_plus_p_theta += ppw->rho_plus_p_theta_gedf;
      ppw->delta_p += ppw->delta_p_gedf;

      ppw->rho_plus_p_tot += (1.+w_gedf)*ppw->pvecback[pba->index_bg_rho_gedf];
    }

    if (pba->has_gedf_2 == _TRUE_) {

      class_call(background_w_gedf_2(pba,a,&w_gedf,&dw_over_da_gedf,&integral_gedf), pba->error_message, ppt->error_message);
      perturbations_gedf_2_sound_speeds(pba,a,w_gedf,dw_over_da_gedf,&ca2_gedf,&cs2_gedf);

      ppw->delta_rho_gedf_2 = ppw->pvecback[pba->index_bg_rho_gedf_2]*y[ppw->pv->index_pt_delta_gedf_2];

      ppw->rho_plus_p_theta_gedf_2 = ppw->pvecback[pba->index_bg_rho_gedf_2]*y[ppw->pv->index_pt_u_gedf_2];

      ppw->delta_p_gedf_2 = cs2_gedf * ppw->delta_rho_gedf_2 + (cs2_gedf-ca2_gedf)*(3*a_prime_over_a*ppw->rho_plus_p_theta_gedf_2/k/k);
      ppw->delta_gedf_2 = y[ppw->pv->index_pt_delta_gedf_2];
      ppw->ca2_gedf_2_output = ca2_gedf;
      ppw->cs2_gedf_2_output = cs2_gedf;
      ppw->u_gedf_2 = y[ppw->pv->index_pt_u_gedf_2];

      ppw->delta_rho += ppw->delta_rho_gedf_2;
      ppw->rho_plus_p_theta += ppw->rho_plus_p_theta_gedf_2;
      ppw->delta_p += ppw->delta_p_gedf_2;

      ppw->rho_plus_p_tot += (1.+w_gedf)*ppw->pvecback[pba->index_bg_rho_gedf_2];
    }

    if (pba->has_edf == _TRUE_) {

      class_call(background_w_edf(pba,a,&w_edf,&dw_over_da_edf,&integral_edf), pba->error_message, ppt->error_message);
          +cs2*k2/(1.+w_fld)*y[pv->index_pt_delta_fld]
          +metric_euler;
      }
      else {
        dy[pv->index_pt_Gamma_fld] = ppw->Gamma_prime_fld; /* Gamma variable of PPF formalism */
      }

    }

    /** GEDF */
    if (pba->has_gedf == _TRUE_) {

        /** - ----> factors w, w_prime, adiabatic sound speed ca2 (all three background-related),
            plus actual sound speed in the fluid rest frame cs2 */

        class_call(background_w_gedf(pba,a,&w_gedf,&dw_over_da_gedf,&integral_gedf), pba->error_message, ppt->error_message);
        perturbations_gedf_sound_speeds(pba,a,w_gedf,dw_over_da_gedf,&ca2_gedf,&cs2_gedf);

        /** - ----> fluid density */

        dy[pv->index_pt_delta_gedf] =
          -(y[pv->index_pt_u_gedf]+(1+w_gedf)*metric_continuity)
          -3.*(cs2_gedf-w_gedf)*a_prime_over_a*y[pv->index_pt_delta_gedf]
          -9.*(cs2_gedf-ca2_gedf)*a_prime_over_a*a_prime_over_a*y[pv->index_pt_u_gedf]/k2;

        // dy[pv->index_pt_delta_edf] =
        //   -(y[pv->index_pt_u_edf]+(1+w_edf)*metric_continuity)
        //   -3.*(cs2-w_edf)*a_prime_over_a*y[pv->index_pt_delta_edf]
        //   -9.*(cs2-ca2)*a_prime_over_a*a_prime_over_a*y[pv->index_pt_u_edf]/k2;

        /** - ----> fluid velocity */

        dy[pv->index_pt_u_gedf] = /* fluid velocity */
          -(1.-3.*cs2_gedf)*a_prime_over_a*y[pv->index_pt_u_gedf]
          +3*a_prime_over_a*(w_gedf - ca2_gedf)*y[pv->index_pt_u_gedf]
          +cs2_gedf*k2*y[pv->index_pt_delta_gedf]
          +metric_euler*(1.+w_gedf);

        // dy[pv->index_pt_u_edf] = /* fluid velocity */
        //   -(1.-3.*cs2)*a_prime_over_a*y[pv->index_pt_u_edf]
        //   +3*a_prime_over_a*(w_edf - ca2)*y[pv->index_pt_u_edf]
        //   +cs2*k2*y[pv->index_pt_delta_edf]
        //   +metric_euler*(1.+w_edf);

        // Turn off the perturbations.
        // dy[pv->index_pt_delta_gedf] = 0.;
        // dy[pv->index_pt_u_gedf] = 0.;
        if (ppt->has_gedf_perturbations == _FALSE_){
            dy[pv->index_pt_delta_gedf] = 0.;
            dy[pv->index_pt_u_gedf] = 0.;
          }

    }

    if (pba->has_gedf_2 == _TRUE_) {

        class_call(background_w_gedf_2(pba,a,&w_gedf,&dw_over_da_gedf,&integral_gedf), pba->error_message, ppt->error_message);
        perturbations_gedf_2_sound_speeds(pba,a,w_gedf,dw_over_da_gedf,&ca2_gedf,&cs2_gedf);

        dy[pv->index_pt_delta_gedf_2] =
          -(y[pv->index_pt_u_gedf_2]+(1+w_gedf)*metric_continuity)
          -3.*(cs2_gedf-w_gedf)*a_prime_over_a*y[pv->index_pt_delta_gedf_2]
          -9.*(cs2_gedf-ca2_gedf)*a_prime_over_a*a_prime_over_a*y[pv->index_pt_u_gedf_2]/k2;

        dy[pv->index_pt_u_gedf_2] =
          -(1.-3.*cs2_gedf)*a_prime_over_a*y[pv->index_pt_u_gedf_2]
          +3*a_prime_over_a*(w_gedf - ca2_gedf)*y[pv->index_pt_u_gedf_2]
          +cs2_gedf*k2*y[pv->index_pt_delta_gedf_2]
          +metric_euler*(1.+w_gedf);

        if (ppt->has_gedf_2_perturbations == _FALSE_){
            dy[pv->index_pt_delta_gedf_2] = 0.;
            dy[pv->index_pt_u_gedf_2] = 0.;
          }

    }
  /* Set new_jacobian flag: */
  jac->new_jacobian = _TRUE_;

  for(j=1;j<=neq;j++){
    nj_ws->yscale[j] = MAX(fabs(y[j]),thresh);
    nj_ws->del[j] = (y[j] + fac[j] * nj_ws->yscale[j]) - y[j];
  }

  /*Select an increment del for a difference approximation to
    column j of dFdy.  The vector fac accounts for experience
    gained in previous calls to numjac.
  */
  for(j=1;j<=neq;j++){
    if (nj_ws->del[j]==0.0){
      for(;;){
    if (fac[j] < facmax){
      fac[j] = MIN(100*fac[j],facmax);
      nj_ws->del[j] = (y[j] + fac[j]*nj_ws->yscale[j]) - y[j];
      if(nj_ws->del[j]==0.0){
        break;
      }
    }
    else{
      nj_ws->del[j] = thresh;
      break;
    }
      }
    }
  }

  /* keep del pointing into region: */
  for(j=1;j<=neq;j++){
    if (fval[j]>=0.0){
      nj_ws->del[j] = fabs(nj_ws->del[j]);
    }
    else{
      nj_ws->del[j] = -fabs(nj_ws->del[j]);
    }
  }

  /* Sparse calculation?*/
  if ((jac->use_sparse)&&(jac->repeated_pattern >= jac->trust_sparse)){
    /* printf("\n Sparse calculation..neq=%d, has grouping=%d",neq,jac->has_grouping);*/
    /* Everything done sparse'ly. Do we have a grouping? */
    if (jac->has_grouping==0){
      jac->max_group = column_grouping(jac->spJ,jac->col_group,jac->col_wi);
      jac->has_grouping = 1;
    }
    colmax = jac->max_group+1;
    /*    printf("\n                ->groups=%d/%d.",colmax,neq);  */
    for(j=1;j<=colmax;j++){
      /*loop over groups */
      group = j-1;
      for(i=1;i<=neq;i++){
        /*Add y-vector.. */
        nj_ws->ydel_Fdel[i][j] = y[i];
        /*Add del of all groupmembers:*/
        if(jac->col_group[i-1]==group) nj_ws->ydel_Fdel[i][j] +=nj_ws->del[i];
      }
    }
  }
  else{
    /*printf("\n Normal calculation..."); */
    /*Normal calculation: */
    colmax = neq;
    for(j=1;j<=neq;j++){
      for(i=1;i<=neq;i++){
        nj_ws->ydel_Fdel[i][j] = y[i];
      }
      nj_ws->ydel_Fdel[j][j] += nj_ws->del[j];
    }
  }

  /* The next section should work regardless of sparse...*/
  /* Evaluate the function at y+delta vectors:*/
  for(j=1;j<=colmax;j++){
    for(i=1;i<=neq;i++){
      nj_ws->yydel[i] = nj_ws->ydel_Fdel[i][j];
    }
    class_call((*derivs)(t,nj_ws->yydel+1,nj_ws->ffdel+1,
               parameters_and_workspace_for_derivs,error_message),
               error_message,error_message);

    *nfe+=1;
    for(i=1;i<=neq;i++) nj_ws->ydel_Fdel[i][j] = nj_ws->ffdel[i];
  }


  /*Using the Fdel array, form the jacobian and construct max-value arrays.
    First we do it for the sparse case, then for the normal case:*/
  if ((jac->use_sparse)&&(jac->repeated_pattern >= jac->trust_sparse)){
    /* Sparse case:*/
    for(j=0;j<neq;j++){
      /*Loop over columns, and assign corresponding group:*/
      group = jac->col_group[j];
      Fdiff_new = 0.0;
      Fdiff_absrm = 0.0;
      for(i=Ap[j];i<Ap[j+1];i++){
        /* Loop over rows in the sparse matrix */
        row = Ai[i]+1;
        /* Do I want to construct the full jacobian? No, that is ugly..*/
        Fdiff_absrm = MAX(Fdiff_absrm,fabs(Fdiff_new));
        Fdiff_new = nj_ws->ydel_Fdel[row][group+1]-fval[row]; /*Remember to access the column of the corresponding group */
        if (fabs(Fdiff_new)>=Fdiff_absrm){
          nj_ws->Rowmax[j+1] = row;
          nj_ws->Difmax[j+1] = Fdiff_new;
        }
        /* Assign value to sparse rep of jacobian: */
        jac->xjac[i] = Fdiff_new/nj_ws->del[j+1];
      }
      /* The maximum numerical value of Fdel in true column j+1*/
      nj_ws->absFdelRm[j+1] = fabs(nj_ws->ydel_Fdel[nj_ws->Rowmax[j+1]][group+1]);
    }
  }
  else{
    /*Normal case:*/
    for(j=1;j<=neq;j++){
      Fdiff_new = 0.0;
      Fdiff_absrm = 0.0;
      for(i=1;i<=neq;i++){
        Fdiff_absrm = MAX(fabs(Fdiff_new),Fdiff_absrm);
        Fdiff_new = nj_ws->ydel_Fdel[i][j] - fval[i];
        dFdy[i][j] = Fdiff_new/nj_ws->del[j];
        /*Find row maximums:*/
        if(fabs(Fdiff_new)>=Fdiff_absrm){
          /* Found new max location in column */
          nj_ws->Rowmax[j] = i;
          nj_ws->Difmax[j] = fabs(Fdiff_new);
        }
      }
      nj_ws->absFdelRm[j] = fabs(nj_ws->ydel_Fdel[nj_ws->Rowmax[j]][j]);
    }
  }

  /* Adjust fac for next call to numjac. */
  for(i=1;i<=neq;i++){
    nj_ws->absFvalue[i] = fabs(fval[i]);
  }
  for(j=1;j<=neq;j++){
    nj_ws->absFvalueRm[j] = nj_ws->absFvalue[nj_ws->Rowmax[j]];
  }

  logjpos = 0;
  for(j=1;j<=neq;j++){
    if (((nj_ws->absFdelRm[j]<TINY)&&(nj_ws->absFvalueRm[j] < TINY))||(fabs(nj_ws->Difmax[j])<TINY)){
      nj_ws->logj[j] = 1;/*.true.*/
"}

